/* Nothing here sends and nothing here writes. This node decides only whether
 * the request is shaped well enough to be ROUTED. Every real decision --
 * which number it leaves from, whether the 24h window is open, whether a
 * template is approved -- belongs to nexus_route_message, not to n8n.
 *
 * request_ref is mandatory and is NOT generated here. A ref minted at call
 * time is a new ref on every retry, which is the same as having none, and
 * nexus_request_send refuses it by name (NEXUS_SEND_REQUEST_REF_REQUIRED). */
const b = ($input.first().json || {}).body || {};

const refuse = (code, why) => [{ json: {
  verdict: 'REFUSE', respond_status: 400, reason_code: code, why,
  wrote_nothing: true, sent_nothing: true,
} }];

const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const tenant_id   = str(b.tenant_id);
const customer    = str(b.customer_external_id);
const intent      = str(b.intent).toUpperCase();
const send_form   = str(b.send_form).toUpperCase();
const request_ref = str(b.request_ref);

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(tenant_id)) {
  return refuse('TENANT_ID_NOT_A_UUID', 'tenant_id must be the id of a row in public.tenants. NEXUS does not default the dealership: a caller that can omit it can pick whose customers get messaged.');
}
if (!/^[0-9]{6,20}$/.test(customer)) {
  return refuse('CUSTOMER_EXTERNAL_ID_NOT_A_WA_ID', 'customer_external_id must be the wa_id exactly as Meta reports it -- digits only, no leading +, no spaces, no display name. The same shape channel_message_events.customer_phone is CHECK-constrained to.');
}
if (!intent)    return refuse('INTENT_MISSING', 'intent decides the template category the policy engine will demand. It is not optional and is not inferred from the body text.');
if (!send_form) return refuse('SEND_FORM_MISSING', 'send_form must be a code in public.channel_send_form (FREEFORM_TEXT, TEMPLATE_TEXT, ...). An unknown shape is refused by the router rather than attempted.');
if (!request_ref) {
  return refuse('REQUEST_REF_MISSING', 'request_ref is the only thing that stops a retry becoming a second message to a real customer. Pass something stable across retries of this same logical send -- the inbound message id, or execution id plus step name. Do not generate a UUID here.');
}

return [{ json: {
  verdict: 'ROUTE',
  tenant_id, customer_external_id: customer, intent, send_form, request_ref,
  message_body:        b.message_body ?? null,
  template_ref:        b.template_ref ?? null,
  template_variables:  b.template_variables ?? null,
  media_ref:           b.media_ref ?? null,
  media_mime:          b.media_mime ?? null,
  requested_by:        str(b.requested_by) || 'n8n:whatsapp-cloud-send',
  max_template_status_age: b.max_template_status_age ?? null,
} }];

/* The directive says SEND. Three things are still checked before the Graph
 * call, and each one refuses rather than guessing.
 *
 *  1. This workflow is the CLOUD transport. If the router picked waha, this
 *     is not our directive to carry -- carrying it anyway is how a template
 *     decision made for one provider gets executed on another.
 *  2. If the ledger says the directive was already routed under this ref AND
 *     already carries a provider result, the send already happened. Stop.
 *     This is the retry guard: Graph has no idempotency key, so the only
 *     thing standing between a retry and a second message is this row.
 *  3. The payload is built from resolved_send_form, never from the caller's
 *     requested_send_form -- the router is allowed to have narrowed it. */
const j  = $input.first().json || {};
const r  = j.result || {};
const id = j.directive_id;
const st = String(j.ledger_state || '');

const stop = (code, why, status) => [{ json: {
  proceed: false, respond_status: status || 409, reason_code: code, why,
  directive_id: id, ledger_state: st, sent_nothing: true,
} }];

if (!id) return stop('DIRECTIVE_NOT_RECORDED', 'The router returned SEND but filed no directive row (' + st + '). NEXUS does not send what it has not written down first.', 500);

if (String(r.provider) !== 'whatsapp_cloud') {
  return stop('NOT_THIS_TRANSPORT', 'The router selected provider ' + r.provider + ' on ' + r.external_identifier + '. This workflow is the WhatsApp Cloud transport and will not carry another provider\u2019s directive. Route it to that provider\u2019s sender, or register Cloud ahead of it.');
}
if (st === 'ALREADY_ROUTED_UNDER_THIS_REQUEST_REF') {
  return stop('ALREADY_SENT_UNDER_THIS_REQUEST_REF', 'This request_ref already has a directive on this dealership. If it is still PENDING a transport may be mid-flight; if it carries a result the message already went. Either way n8n does not send a second one. Read channel_send_directive for directive_id ' + id + '.', 200);
}

const form = String(r.resolved_send_form || '');
const to   = String(r.customer_external_id || '');
let payload;

if (form === 'FREEFORM_TEXT') {
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to,
              type: 'text', text: { preview_url: false, body: String(r.message_body || '') } };
} else if (form === 'TEMPLATE_TEXT' || form === 'TEMPLATE_MEDIA_HEADER') {
  const v = r.template_variables || {};
  const body_params = Array.isArray(v.body) ? v.body.map(t => ({ type: 'text', text: String(t) })) : [];
  const components = body_params.length ? [{ type: 'body', parameters: body_params }] : [];
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to,
              type: 'template',
              template: { name: String(r.template_ref),
                          language: { code: String(v.language_code || 'en') },
                          components } };
} else if (form === 'FREEFORM_IMAGE' || form === 'FREEFORM_DOCUMENT' || form === 'FREEFORM_VIDEO' || form === 'FREEFORM_AUDIO') {
  const kind = form.replace('FREEFORM_', '').toLowerCase();
  const ref  = String(r.media_ref || '');
  const isUrl = /^https:\/\//i.test(ref);
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to,
              type: kind, [kind]: isUrl ? { link: ref } : { id: ref } };
} else {
  return stop('SEND_FORM_NOT_IMPLEMENTED_IN_TRANSPORT', 'The router resolved send form ' + (form || '(empty)') + ', which this transport cannot build a Graph payload for. It refuses rather than downgrading the shape -- an INTERACTIVE_LIST silently flattened to a text message is a different message from the one that was authorised.', 501);
}

return [{ json: {
  proceed: true,
  directive_id: id,
  phone_number_id: String(r.external_identifier || ''),
  resolved_send_form: form,
  payload,
} }];

/* Both Graph outcomes land here, and BOTH write a row. Five of six existing
 * WhatsApp send sites in this repo use onError: continueRegularOutput and go
 * on to record "we said this" whether or not anything left the building.
 * This node exists so that does not happen again: it reads the status code
 * and the body and names what actually occurred.
 *
 * ACCEPTED is not DELIVERED and is not READ. The wamid is the only thing a
 * later delivery feed can reconcile against, so an accept without one is
 * refused by nexus_record_send_result rather than recorded as a success. */
const src = $input.first().json || {};
const d   = $('Compose Graph Payload').first().json || {};

const status = Number(src.statusCode ?? src.status ?? 0);
const body   = src.body ?? src;
const wamid  = body && body.messages && body.messages[0] ? body.messages[0].id : null;
const gerr   = (body && body.error) ? body.error : null;

let result, error_code = null, error_detail = null, respond_status = 200;

if (status >= 200 && status < 300 && wamid) {
  result = 'ACCEPTED_BY_PROVIDER';
} else if (status >= 200 && status < 300 && !wamid) {
  /* A 2xx with no message id is not an accept we can prove. Recording it as
     accepted would make "accepted" unfalsifiable, which is the exact shape
     nexus_record_send_result refuses. Call it a transport error: whether the
     provider saw it is UNKNOWN, which is the honest answer. */
  result = 'TRANSPORT_ERROR';
  error_code = 'GRAPH_2XX_WITHOUT_WAMID';
  error_detail = 'Graph returned ' + status + ' with no messages[0].id. Raw body: ' + JSON.stringify(body).slice(0, 900);
  respond_status = 502;
} else if (status >= 400 && status < 600 && gerr) {
  /* A policy rejection (131047 outside window, 132000 template mismatch,
     133010 not registered) is NOT a transport failure and must never be
     re-driven as one. It is recorded and it stops here. */
  result = 'REJECTED_BY_PROVIDER';
  error_code = String(gerr.code ?? status) + (gerr.error_subcode ? '/' + gerr.error_subcode : '');
  error_detail = String(gerr.message || '') + (gerr.error_data && gerr.error_data.details ? ' | ' + gerr.error_data.details : '') + ' | fbtrace_id=' + String(gerr.fbtrace_id || 'none');
  respond_status = 200;
} else {
  result = 'TRANSPORT_ERROR';
  error_code = src.error ? 'N8N_REQUEST_FAILED' : ('GRAPH_HTTP_' + (status || 'NO_RESPONSE'));
  error_detail = 'The call did not complete, so whether Meta saw it is UNKNOWN -- not "it was not sent". Re-drive only under the same request_ref so idempotency decides. Detail: ' + JSON.stringify(src.error ?? body ?? {}).slice(0, 900);
  respond_status = 502;
}

return [{ json: {
  directive_id: d.directive_id,
  result, provider_message_id: wamid, error_code, error_detail,
  respond_status,
  resolved_send_form: d.resolved_send_form,
  graph_status: status,
} }];
